from abc import ABC, abstractmethod

class Dyr(ABC):
    @abstractmethod
    def lyd(self):
        pass

    @abstractmethod
    def beveg(self):
        pass

    def presenter(self):
        print(f"Lyd: {self.lyd()}")
        print(f"Bevegelse: {self.beveg()}")
        print()

class Fisk(Dyr):
    def lyd(self):
        return "Blub blub"

    def beveg(self):
        return "Svømmer i vannet"

class Fugl(Dyr):
    def lyd(self):
        return "Kvitrer!"

    def beveg(self):
        return "Flyr i luften"

# Test
fisk = Fisk()
fisk.presenter()
# Lyd: Blub blub
# Bevegelse: Svømmer i vannet

fugl = Fugl()
fugl.presenter()
# Lyd: Kvitrer!
# Bevegelse: Flyr i luften
```

Den abstrakte klassen `Dyr` tvinger subklassene til å implementere `lyd()` og `beveg()`, mens `presenter()` er en felles metode som bruker disse.

